CREATE TABLE public.cdp_segment_events (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    customer_id uuid NOT NULL REFERENCES public.customers(id) ON DELETE CASCADE,
    workspace_channel text NOT NULL,
    sync_status text NOT NULL DEFAULT 'pending',
    client_ip inet,
    idempotency_key text NOT NULL,
    payload jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT uq_cdp_segment_events_idempotency UNIQUE (tenant_id, idempotency_key)
);

CREATE INDEX idx_cdp_segment_events_tenant_customer ON public.cdp_segment_events (tenant_id, customer_id);
CREATE INDEX idx_cdp_segment_events_sync_status ON public.cdp_segment_events (tenant_id, sync_status) WHERE sync_status = 'pending';
CREATE INDEX idx_cdp_segment_events_created_at ON public.cdp_segment_events (created_at DESC);

ALTER TABLE public.cdp_segment_events ENABLE ROW LEVEL SECURITY;

CREATE POLICY policy_cdp_segment_events_tenant_isolation ON public.cdp_segment_events
    FOR ALL
    TO application
    USING (tenant_id = (auth.jwt() ->> 'tenant_id')::uuid)
    WITH CHECK (tenant_id = (auth.jwt() ->> 'tenant_id')::uuid);

CREATE OR REPLACE FUNCTION public.fn_prevent_cdp_segment_events_updates()
RETURNS TRIGGER AS $$
BEGIN
    RAISE EXCEPTION 'Table public.cdp_segment_events is append-only. Updates and deletes are not permitted.';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_cdp_segment_events_append_only
BEFORE UPDATE OR DELETE ON public.cdp_segment_events
FOR EACH ROW EXECUTE FUNCTION public.fn_prevent_cdp_segment_events_updates();

CREATE VIEW public.vw_cdp_segment_events AS
SELECT 
    id,
    customer_id,
    workspace_channel,
    sync_status,
    client_ip,
    idempotency_key,
    payload,
    created_at
FROM public.cdp_segment_events;

GRANT SELECT ON public.cdp_segment_events TO readonly_user;
GRANT SELECT, INSERT ON public.cdp_segment_events TO application;
GRANT ALL ON public.cdp_segment_events TO deployer;
GRANT SELECT ON public.vw_cdp_segment_events TO application, readonly_user;

