$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_data_export_audits_append_only
BEFORE UPDATE OR DELETE ON public.data_export_audits
FOR EACH ROW EXECUTE FUNCTION public.fn_prevent_data_export_audits_updates();

