GROUP BY tenant_id, export_format;

GRANT SELECT ON public.data_export_audits TO application;
GRANT INSERT ON public.data_export_audits TO application;
GRANT SELECT ON public.vw_tenant_export_summary TO application;
GRANT SELECT ON public.data_export_audits TO readonly_user;
GRANT SELECT ON public.vw_tenant_export_summary TO readonly_user;

